class Solution:
    def maxSubArray(self, nums: list[int]) -> int:
        best = nums[0]
        for l in range(len(nums)):
            for r in range(l, len(nums)):
                total = 0
                for i in range(l, r+1):
                    total += nums[i]
                best = max(best, total)
        return best

